// The existing single-edit API works. Preserve it while extending this module.
function checkEdit(source,edit){
  if(typeof source!=='string'||edit===null||typeof edit!=='object'||Array.isArray(edit)
    ||!Number.isSafeInteger(edit.start)||!Number.isSafeInteger(edit.end)
    ||edit.start<0||edit.start>edit.end||edit.end>source.length
    ||typeof edit.before!=='string'||typeof edit.after!=='string')throw Error('invalid edit');
  if(source.slice(edit.start,edit.end)!==edit.before)throw Error('preimage mismatch');
}
export function applyEdit(source,edit){
  checkEdit(source,edit);
  return source.slice(0,edit.start)+edit.after+source.slice(edit.end);
}
export function applyTransaction(source,edits){
  if(typeof source!=='string')throw Error('invalid source');
  if(!Array.isArray(edits))throw Error('invalid edits');

  // Validate every edit against the original source before applying anything.
  const plan=edits.map(edit=>{
    checkEdit(source,edit);
    return {start:edit.start,end:edit.end,after:edit.after};
  });

  // Nonempty ranges must not overlap; adjacency is allowed.
  const ranges=plan.filter(e=>e.start<e.end).sort((a,b)=>a.start-b.start||a.end-b.end);
  for(let i=1;i<ranges.length;i++){
    if(ranges[i].start<ranges[i-1].end)throw Error('conflicting edits');
  }

  // Insertions must sit at distinct positions...
  const points=plan.filter(e=>e.start===e.end).map(e=>e.start).sort((a,b)=>a-b);
  for(let i=1;i<points.length;i++){
    if(points[i]===points[i-1])throw Error('conflicting edits');
  }

  // ...and outside every nonempty range, endpoints included.
  for(const p of points){
    let lo=0,hi=ranges.length-1,found=-1;
    while(lo<=hi){
      const mid=(lo+hi)>>1;
      if(ranges[mid].start<=p){found=mid;lo=mid+1;}else{hi=mid-1;}
    }
    if(found>=0&&p<=ranges[found].end)throw Error('conflicting edits');
  }

  // Apply simultaneously: every edit still speaks original-source coordinates.
  const ordered=plan.slice().sort((a,b)=>a.start-b.start||a.end-b.end);
  let text='',cursor=0;
  for(const e of ordered){
    text+=source.slice(cursor,e.start)+e.after;
    cursor=e.end;
  }
  text+=source.slice(cursor);
  return {text,applied:plan.length};
}

// Add the JSON-file CLI described by the work order without import side effects.
function runCli(argv){
  if(argv.length!==1)throw Error('usage: node patch-transaction.js INPUT_JSON_FILE');
  const raw=readFileSync(argv[0],'utf8');
  let parsed;
  try{parsed=JSON.parse(raw);}catch(err){throw Error('invalid JSON: '+err.message);}
  if(parsed===null||typeof parsed!=='object'||Array.isArray(parsed))throw Error('invalid input object');
  return JSON.stringify(applyTransaction(parsed.source,parsed.edits));
}

let readFileSync;
if(process.argv[1]){
  const {pathToFileURL}=await import('node:url');
  let self;
  try{self=pathToFileURL(process.argv[1]).href;}catch{self=undefined;}
  if(self===import.meta.url){
    ({readFileSync}=await import('node:fs'));
