import {applyTransaction,applyEdit} from './patch-transaction.js';
// randomized: compare against a brute-force reference
const rnd=(n)=>Math.floor(Math.random()*n);
let checked=0,conflicts=0;
for(let t=0;t<20000;t++){
  const src='abcdefgh'.slice(0,rnd(9));
  const n=rnd(4);
  const edits=[];
  for(let i=0;i<n;i++){const a=rnd(src.length+1),b=rnd(src.length+1);const s=Math.min(a,b),e=Math.max(a,b);
    edits.push({start:s,end:e,before:src.slice(s,e),after:'<'+i+'>'});}
  // brute-force conflict check
  let conflict=false;
  for(let i=0;i<n;i++)for(let j=i+1;j<n;j++){
    const A=edits[i],B=edits[j];
    const ai=A.start===A.end,bi=B.start===B.end;
    if(!ai&&!bi){if(A.start<B.end&&B.start<A.end)conflict=true;}
    else if(ai&&bi){if(A.start===B.start)conflict=true;}
    else {const I=ai?A:B,R=ai?B:A;if(R.start<=I.start&&I.start<=R.end)conflict=true;}
  }
  let got=null,threw=false;
  try{got=applyTransaction(src,edits);}catch{threw=true;}
  if(threw!==conflict)throw new Error('conflict mismatch '+JSON.stringify({src,edits,conflict}));
  if(conflict){conflicts++;continue;}
  // reference: apply right-to-left
  const sorted=[...edits].sort((a,b)=>b.start-a.start);
  let ref=src;for(const e of sorted)ref=applyEdit(ref,{...e,before:src.slice(e.start,e.end)});
  if(ref!==got.text||got.applied!==n)throw new Error('text mismatch '+JSON.stringify({src,edits,ref,got}));
  // permutation independence
  for(let k=0;k<3;k++){const p=[...edits].sort(()=>Math.random()-0.5);
    if(JSON.stringify(applyTransaction(src,p))!==JSON.stringify(got))throw new Error('order dependence');}
  checked++;
}
console.log('ok non-conflicting:',checked,'conflicting:',conflicts);
"

