+
 // Add the JSON-file CLI described by the work order without import side effects.
+import {readFileSync,realpathSync} from 'node:fs';
+import {pathToFileURL} from 'node:url';
+
+function runCli(argv){
+  if(argv.length!==1)throw Error('usage: node patch-transaction.js INPUT_JSON_FILE');
+  const raw=readFileSync(argv[0],'utf8');
+  let parsed;
+  try{parsed=JSON.parse(raw);}catch(err){throw Error('invalid JSON: '+err.message);}
+  if(parsed===null||typeof parsed!=='object'||Array.isArray(parsed))throw Error('invalid input object');
+  return JSON.stringify(applyTransaction(parsed.source,parsed.edits));
+}
+
+function isMain(){
+  const entry=process.argv[1];
+  if(typeof entry!=='string'||entry==='')return false;
+  for(const candidate of [entry,tryRealpath(entry)]){
+    if(candidate===undefined)continue;
+    try{if(pathToFileURL(candidate).href===import.meta.url)return true;}catch{}
+  }
+  return false;
+}
+function tryRealpath(p){
+  try{return realpathSync(p);}catch{return undefined;}
+}
+
+if(isMain()){
+  try{
+    process.stdout.write(runCli(process.argv.slice(2))+'\n');
+  }catch(err){
+    process.stderr.write((err&&err.message?err.message:String(err))+'\n');
