import test from 'node:test';
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {mkdtempSync,rmSync,writeFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join,dirname} from 'node:path';
import {fileURLToPath} from 'node:url';
import {applyEdit,applyTransaction} from '../patch-transaction.js';

const MODULE=join(dirname(fileURLToPath(import.meta.url)),'..','patch-transaction.js');
const edit=(start,end,before,after)=>({start,end,before,after});

test('validates source and edits container',()=>{
  assert.throws(()=>applyTransaction(null,[]),Error);
  assert.throws(()=>applyTransaction(['a'],[]),Error);
  assert.throws(()=>applyTransaction('abc',null),Error);
  assert.throws(()=>applyTransaction('abc',{length:0}),Error);
  assert.throws(()=>applyTransaction('abc','' ),Error);
});

test('rejects malformed edits without coercion',()=>{
  for(const bad of [null,[0,1,'a','b'],'x',42,{start:'0',end:1,before:'a',after:'b'},
    {start:0,end:1,before:'a'},{start:0,end:1,before:'a',after:1},
    {start:-1,end:0,before:'',after:''},{start:1.5,end:2,before:'',after:''},
    {start:2,end:1,before:'',after:''},{start:0,end:9,before:'abc',after:''}]){
    assert.throws(()=>applyTransaction('abc',[bad]),Error,JSON.stringify(bad));
  }
});

test('preimage must match and unknown fields are ignored',()=>{
  assert.throws(()=>applyTransaction('abc',[edit(0,1,'b','x')]),Error);
  const e={start:0,end:1,before:'a',after:'X',extra:{nope:true}};
  assert.deepEqual(applyTransaction('abc',[e]),{text:'Xbc',applied:1});
});

test('order independence over a permuted transaction',()=>{
  const source='hello brave new world';
  const edits=[edit(0,5,'hello','HI'),edit(6,11,'brave','bold'),edit(16,21,'world','earth')];
  const expected={text:'HI bold new earth',applied:3};
  assert.deepEqual(applyTransaction(source,edits),expected);
  assert.deepEqual(applyTransaction(source,[edits[2],edits[0],edits[1]]),expected);
  assert.deepEqual(applyTransaction(source,[edits[1],edits[2],edits[0]]),expected);
});

test('does not mutate the input array or its objects',()=>{
  const edits=[edit(3,5,'de','X'),edit(0,1,'a','LONG')];
  const snapshot=JSON.parse(JSON.stringify(edits));
  const order=[edits[0],edits[1]];
  applyTransaction('abcdef',edits);
  assert.deepEqual(edits,snapshot);
  assert.equal(edits[0],order[0]);
  assert.equal(edits[1],order[1]);
});

test('overlapping nonempty ranges conflict, adjacency does not',()=>{
  assert.throws(()=>applyTransaction('abcdef',[edit(0,3,'abc','x'),edit(2,5,'cde','y')]),Error);
  assert.throws(()=>applyTransaction('abcdef',[edit(0,4,'abcd','x'),edit(1,2,'b','y')]),Error);
  assert.throws(()=>applyTransaction('abcdef',[edit(1,2,'b','y'),edit(0,4,'abcd','x')]),Error);
  assert.deepEqual(applyTransaction('abcdef',[edit(0,3,'abc','x'),edit(3,6,'def','y')]),
    {text:'xy',applied:2});
});

test('insertion conflicts at both endpoints and inside a range',()=>{
  for(const pos of [1,2,3]){
    assert.throws(()=>applyTransaction('abcde',[edit(1,3,'bc','X'),edit(pos,pos,'','I')]),Error,
      'position '+pos);
    assert.throws(()=>applyTransaction('abcde',[edit(pos,pos,'','I'),edit(1,3,'bc','X')]),Error,
      'position '+pos+' reversed');
  }
  assert.deepEqual(applyTransaction('abcde',[edit(1,3,'bc','X'),edit(0,0,'','I')]),
    {text:'IaXde',applied:2});
  assert.deepEqual(applyTransaction('abcde',[edit(1,3,'bc','X'),edit(4,4,'','I')]),
    {text:'aXdIe',applied:2});
});

test('duplicate insertions conflict even when empty',()=>{
  assert.throws(()=>applyTransaction('abc',[edit(1,1,'','x'),edit(1,1,'','y')]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(1,1,'',''),edit(1,1,'','')]),Error);
  assert.throws(()=>applyTransaction('',[edit(0,0,'','a'),edit(0,0,'','b')]),Error);
  assert.deepEqual(applyTransaction('abc',[edit(1,1,'','x'),edit(2,2,'','y')]),
    {text:'axbyc',applied:2});
});

test('insertions at the very end and no-op edits count',()=>{
  assert.deepEqual(applyTransaction('abc',[edit(3,3,'','!')]),{text:'abc!',applied:1});
  assert.deepEqual(applyTransaction('abcd',[edit(0,1,'a','a'),edit(2,2,'','')]),
    {text:'abcd',applied:2});
  assert.throws(()=>applyTransaction('abc',[edit(0,1,'a','a'),edit(1,1,'','')]),Error);
  assert.deepEqual(applyTransaction('abc',[edit(0,3,'abc','abc')]),{text:'abc',applied:1});
});

test('preserves CRLF, whitespace and final newline',()=>{
  const source='line one\r\n  indented\ttab\r\nlast\n';
  const out=applyTransaction(source,[edit(0,4,'line','LINE')]);
  assert.equal(out.text,'LINE one\r\n  indented\ttab\r\nlast\n');
  const insert=applyTransaction(source,[edit(source.length,source.length,'','tail\r\n')]);
  assert.equal(insert.text,source+'tail\r\n');
});

test('surrogate pairs use UTF-16 code unit offsets',()=>{
  const source='a\u{1F600}b';
  assert.equal(source.length,4);
  assert.deepEqual(applyTransaction(source,[edit(1,3,'\u{1F600}','e')]),{text:'aeb',applied:1});
  assert.throws(()=>applyTransaction(source,[edit(1,2,'\u{1F600}','e')]),Error);
});

test('a conflicting transaction never produces partial output',()=>{
  const source='abcdef';
  assert.throws(()=>applyTransaction(source,[edit(0,2,'ab','X'),edit(1,3,'bc','Y')]),Error);
  assert.deepEqual(applyTransaction(source,[]),{text:source,applied:0});
});

test('single-edit API is untouched',()=>{
  assert.equal(applyEdit('abc',edit(1,2,'b','LONG')),'aLONGc');
  assert.equal(applyEdit('',edit(0,0,'','x')),'x');
  assert.throws(()=>applyEdit('abc',edit(1,2,'wrong','x')),Error);
});

function cli(args,cwd){
  try{
    const stdout=execFileSync(process.execPath,[MODULE,...args],
      {cwd,encoding:'utf8',stdio:['ignore','pipe','pipe']});
    return {code:0,stdout,stderr:''};
  }catch(err){
    return {code:err.status,stdout:err.stdout,stderr:err.stderr};
  }
}

test('CLI',async t=>{
  const dir=mkdtempSync(join(tmpdir(),'patch-tx-'));
  const write=(name,text)=>{const p=join(dir,name);writeFileSync(p,text);return p;};
  try{
    await t.test('prints one result JSON line on success',()=>{
      const file=write('ok.json',JSON.stringify({
        source:'abcdef',
        edits:[{start:0,end:1,before:'a',after:'LONG'},{start:3,end:5,before:'de',after:'X'}],
        ignored:true,
      }));
      const r=cli([file],dir);
      assert.equal(r.code,0);
      assert.equal(r.stderr,'');
      assert.equal(r.stdout,JSON.stringify({text:'LONGbcXf',applied:2})+'\n');
    });

    await t.test('handles an empty transaction',()=>{
      const file=write('empty.json',JSON.stringify({source:'tail\r\n',edits:[]}));
      const r=cli([file],dir);
      assert.equal(r.code,0);
      assert.deepEqual(JSON.parse(r.stdout),{text:'tail\r\n',applied:0});
    });

    await t.test('reads UTF-8 input',()=>{
      const file=write('utf8.json',JSON.stringify({
        source:'café \u{1F600}',
        edits:[{start:0,end:4,before:'café',after:'tea'}],
      }));
      const r=cli([file],dir);
      assert.equal(r.code,0);
      assert.equal(JSON.parse(r.stdout).text,'tea \u{1F600}');
    });

    await t.test('exits 2 with stderr and no stdout on bad input',()=>{
      const conflict=write('conflict.json',JSON.stringify({
        source:'abcd',
        edits:[{start:0,end:2,before:'ab',after:'x'},{start:2,end:2,before:'',after:'y'}],
      }));
      const badJson=write('bad.json','{not json');
      const badShape=write('shape.json',JSON.stringify({source:5,edits:[]}));
      const cases=[[],[conflict,conflict],[join(dir,'missing.json')],[dir],
        [badJson],[badShape],[conflict]];
      for(const args of cases){
        const r=cli(args,dir);
        assert.equal(r.code,2,JSON.stringify(args));
        assert.equal(r.stdout,'',JSON.stringify(args));
        assert.ok(r.stderr.length>0,JSON.stringify(args));
      }
    });

    await t.test('importing does not run the CLI',()=>{
      const probe=write('probe.mjs',
        `import * as m from ${JSON.stringify(MODULE)};\n`+
        `process.stdout.write(typeof m.applyTransaction);\n`);
      const r=cli([],dir);
      assert.equal(r.code,2);
      const out=execFileSync(process.execPath,[probe,'extra','args'],
        {cwd:dir,encoding:'utf8',stdio:['ignore','pipe','pipe']});
      assert.equal(out,'function');
    });
  }finally{
    rmSync(dir,{recursive:true,force:true});
  }
});

